query PrDetails($owner: String!, $repo: String!) { rateLimit { remaining resetAt } pr0: repository(owner: $owner, name: $repo) { pullRequest(number: 369) { id number url title updatedAt state isDraft mergeable mergeStateStatus
 author { login } headRefName headRefOid
 statusCheckRollup { contexts(first: 100) { nodes {
 ... on CheckRun { __typename name status conclusion startedAt completedAt checkSuite { createdAt } isRequired(pullRequestNumber: 369) }
 ... on StatusContext { __typename context state createdAt isRequired(pullRequestNumber: 369) }
 } pageInfo { hasNextPage endCursor } } }
 reviews(first: 100) { nodes { id author { __typename login } state commit { oid } submittedAt } pageInfo { hasNextPage endCursor } }
 comments(last: 100) { nodes { id author { __typename login } createdAt } pageInfo { hasPreviousPage startCursor } }
 reviewThreads(first: 100) { nodes { isResolved } pageInfo { hasNextPage endCursor } }
 reviewRequests(first: 100) { nodes { requestedReviewer { __typename ... on Bot { login } ... on Mannequin { login } ... on User { login } ... on Team { slug } ... on EnterpriseTeam { slug } } asCodeOwner } pageInfo { hasNextPage endCursor } }
 closingIssuesReferences(first: 100) { nodes { number repository { nameWithOwner } } pageInfo { hasNextPage endCursor } } } }
